local reverse
function AT.GetForeverObjectiveQuests(item)
 if not reverse then
  reverse={}
  for quest,row in pairs(AT.ForeverQuestFacts) do
   for i=3,#row do
    local id=row[i][1]
    reverse[id]=reverse[id] or {}
    reverse[id][quest]=true
   end
  end
 end
 return reverse[item]
end

